// Amplitud del ruido en voltios: cada copia suma un valor al azar entre -AMPLITUD y +AMPLITUD
const AMPLITUD = 0.5;
const ruido = () => (Math.random() - 0.5) * 2 * AMPLITUD;

let analogica = 3.7;  // un valor analógico cualquiera, en voltios
let digital = 5;      // un bit 1, enviado como 5 V

for (let copia = 1; copia <= 10; copia++) {
  analogica += ruido();                 // lo analógico arrastra todo el ruido acumulado
  digital += ruido();                   // lo digital también lo recibe...
  digital = digital > 2.5 ? 5 : 0;      // ...pero se regenera: se decide 0 o 5 contra el umbral
  console.log(`copia ${copia}: analógica ${analogica.toFixed(2)} V | digital ${digital} V`);
}
